  p=read(run_dir(s,'RTKLIB')/'native/HX02_HEADING_TABLES/HX02_HEADING_TABLE_RTKLIB.csv');n=pd.read_csv(p);n['native_time']=n.time_unix_s-SEQ[s][0];n['grid']=np.rint(n.gps_tow_seconds/.2).astype(int)
  d=pd.read_csv(O/f'{s}_RTKLIB_POS_DETAIL.csv.gz');d['grid']=np.rint((d.time+SEQ[s][0]+18-315964800-2408*604800)/.2).astype(int);j=d.merge(n[['grid','native_time','valid','rtklib_q']],on='grid',how='left');j['sequence']=s;j['native_in_window']=j.native_time.between(SEQ[s][1],SEQ[s][2]);j['pos_minus_native_s']=j.time-j.native_time
  write(f'{s}_RTKLIB_TAG_ASSOCIATION.csv.gz',j);out+=j[(j.Q==1)&(~j.native_in_window|j.valid.ne(1))].to_dict('records')
