def validate():
 checks=[]
 for s in SEQ:
  for r in [1,2]:
   d=pd.read_csv(O/f'{s}_R{r}_CMC_DETAIL.csv.gz');a=d[d.proxy=='dual_frequency_MP'];keys=['gnss','sv','signal','frequency_id','arc','second_signal','second_arc','proxy'];n=a.groupby(keys).time.transform('size');checks.append(dict(check=f'{s}_R{r}_single_epoch_arc_is_unavailable',passed=bool(a.loc[n<2,'residual_m'].isna().all())))
  d=pd.read_csv(O/f'{s}_FRACTIONAL_DD_DETAIL.csv.gz');checks.append(dict(check=s+'_DD_wrap_range',passed=bool(((d.fractional_cycles>-.5)&(d.fractional_cycles<=.5)).all())))
  j=pd.read_csv(O/f'{s}_FIX_DETAIL.csv.gz');checks.append(dict(check=s+'_fix_states_partition',passed=bool(((j.both_fixed.astype(int)+j.one_fixed.astype(int)+j.neither_fixed.astype(int))==1).all())))
 pins=json.loads((O/'DG01_RAW_PINS.json').read_text())
 for p in pins:checks.append(dict(check=p['sequence']+'_R'+str(p['receiver'])+'_'+p['stream']+'_sha256',passed=sha(p['path'])==p['expected']))
 assert all(x['passed'] for x in checks),checks
 (R/'DG01_CHECKS.json').write_text(json.dumps(checks,indent=2)+'\n')
 return checks
def table(df,cols=None):
 if cols is not None:df=df[cols]
 def f(v):
  if pd.isna(v):return 'UNAVAILABLE'
  if isinstance(v,(float,np.floating)):return str(int(v)) if float(v).is_integer() else f'{v:.3f}'
  return str(v).replace('|','\\|')
 return '| '+' | '.join(df.columns)+' |\n| '+' | '.join('---' for _ in df.columns)+' |\n'+'\n'.join('| '+' | '.join(f(v) for v in row)+' |' for row in df.itertuples(index=False,name=None))
